/* ---------- Site behaviour ---------- */
(function () {
    const root = document.documentElement;
    root.classList.remove('no-js');

    function safeGet(key) { try { return localStorage.getItem(key); } catch (e) { return null; } }
    function safeSet(key, val) { try { localStorage.setItem(key, val); } catch (e) { } }

    function ready(fn) {
        if (document.readyState !== 'loading') fn();
        else document.addEventListener('DOMContentLoaded', fn);
    }

    ready(function () {
        /* Theme toggle (initial theme is set inline in <head> to avoid a flash) */
        const themeToggle = document.getElementById('theme-toggle');
        const syncThemeIcon = () => {
            if (!themeToggle) return;
            const dark = root.getAttribute('data-theme') === 'dark';
            themeToggle.innerHTML = dark ? '<i class="fa-solid fa-sun"></i>' : '<i class="fa-solid fa-moon"></i>';
            themeToggle.setAttribute('aria-label', dark ? 'Switch to light mode' : 'Switch to dark mode');
        };
        syncThemeIcon();
        if (themeToggle) {
            themeToggle.addEventListener('click', () => {
                const next = root.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
                root.setAttribute('data-theme', next);
                safeSet('theme', next);
                syncThemeIcon();
            });
        }

        /* Mobile menu */
        const menuToggle = document.querySelector('.mobile-menu-toggle');
        const navLinks = document.querySelector('.nav-links');
        if (menuToggle && navLinks) {
            const setMenu = (open) => {
                navLinks.classList.toggle('active', open);
                menuToggle.setAttribute('aria-expanded', String(open));
                const icon = menuToggle.querySelector('i');
                if (icon) icon.className = open ? 'fa-solid fa-xmark' : 'fa-solid fa-bars';
            };
            menuToggle.setAttribute('aria-expanded', 'false');
            menuToggle.addEventListener('click', (e) => {
                e.stopPropagation();
                setMenu(!navLinks.classList.contains('active'));
            });
            navLinks.querySelectorAll('a').forEach(a => a.addEventListener('click', () => setMenu(false)));
            document.addEventListener('click', (e) => {
                if (navLinks.classList.contains('active') && !navLinks.contains(e.target)) setMenu(false);
            });
            document.addEventListener('keydown', (e) => {
                if (e.key === 'Escape' && navLinks.classList.contains('active')) { setMenu(false); menuToggle.focus(); }
            });
            window.matchMedia('(min-width: 901px)').addEventListener('change', (m) => { if (m.matches) setMenu(false); });
        }

        /* News ticker: duplicate items so the loop is seamless, speed based on length */
        const ticker = document.querySelector('.ticker');
        if (ticker && !ticker.dataset.cloned) {
            Array.from(ticker.children).forEach(item => {
                const clone = item.cloneNode(true);
                clone.setAttribute('aria-hidden', 'true');
                clone.querySelectorAll('a').forEach(a => a.setAttribute('tabindex', '-1'));
                ticker.appendChild(clone);
            });
            ticker.dataset.cloned = 'true';
            const half = ticker.scrollWidth / 2;
            ticker.style.setProperty('--ticker-duration', Math.max(30, half / 70) + 's');
        }

        /* Scroll reveal */
        const revealEls = document.querySelectorAll('.animate-on-scroll');
        if ('IntersectionObserver' in window) {
            const observer = new IntersectionObserver((entries) => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        entry.target.classList.add('visible');
                        observer.unobserve(entry.target);
                    }
                });
            }, { threshold: 0.08, rootMargin: '0px 0px -40px 0px' });
            revealEls.forEach(el => observer.observe(el));
        } else {
            revealEls.forEach(el => el.classList.add('visible'));
        }

        /* Modals: any element with data-modal="<id>" (or legacy *-trigger classes) opens one */
        const legacy = {
            'graduation-trigger': 'graduation-modal',
            'applications-trigger': 'applications-modal',
            'ellis-trigger': 'ellis-modal',
            'republic-day-trigger': 'republic-modal'
        };
        Object.keys(legacy).forEach(cls => {
            document.querySelectorAll('.' + cls + ', #' + cls).forEach(el => {
                if (!el.dataset.modal) el.dataset.modal = legacy[cls];
            });
        });

        let openModal = null;
        let lastFocus = null;

        const closeModal = () => {
            if (!openModal) return;
            const m = openModal;
            openModal = null;
            m.classList.remove('show');
            document.body.classList.remove('modal-open');
            setTimeout(() => { m.style.display = 'none'; }, 250);
            if (lastFocus) lastFocus.focus();
        };

        const showModal = (modal) => {
            if (openModal) closeModal();
            lastFocus = document.activeElement;
            modal.style.display = 'block';
            void modal.offsetWidth;
            modal.classList.add('show');
            modal.scrollTop = 0;
            document.body.classList.add('modal-open');
            openModal = modal;
            const closeBtn = modal.querySelector('.close-modal');
            if (closeBtn) closeBtn.focus({ preventScroll: true });
        };

        document.querySelectorAll('[data-modal]').forEach(trigger => {
            const modal = document.getElementById(trigger.dataset.modal);
            if (!modal) return;
            const activate = (e) => { e.preventDefault(); showModal(modal); };
            trigger.addEventListener('click', activate);
            if (trigger.tagName !== 'A' && trigger.tagName !== 'BUTTON') {
                trigger.setAttribute('role', 'button');
                trigger.setAttribute('tabindex', '0');
                trigger.addEventListener('keydown', (e) => {
                    if (e.key === 'Enter' || e.key === ' ') activate(e);
                });
            }
        });

        document.querySelectorAll('.modal').forEach(modal => {
            modal.setAttribute('role', 'dialog');
            modal.setAttribute('aria-modal', 'true');
            const title = modal.querySelector('h2');
            if (title) {
                if (!title.id) title.id = modal.id + '-title';
                modal.setAttribute('aria-labelledby', title.id);
            }
            modal.addEventListener('click', (e) => {
                if (e.target === modal || e.target.closest('.close-modal')) closeModal();
            });
        });

        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape' && openModal) closeModal();
        });

        /* Live Google Scholar metrics (scholar.json is refreshed daily by a GitHub Action) */
        loadScholar();

        /* Footer year */
        document.querySelectorAll('[data-year]').forEach(el => { el.textContent = new Date().getFullYear(); });

        /* Publications page filter */
        const filterBar = document.getElementById('publications-filter');
        if (filterBar) {
            const pubs = Array.from(document.querySelectorAll('#full-publications-list .selected-publication'));
            const headings = Array.from(document.querySelectorAll('#full-publications-list .year-heading'));
            const buttons = Array.from(filterBar.querySelectorAll('.filter-btn'));

            buttons.forEach(btn => {
                const f = btn.dataset.filter;
                const n = f === 'all' ? pubs.length : pubs.filter(p => p.classList.contains(f)).length;
                const c = document.createElement('span');
                c.className = 'count';
                c.textContent = n;
                btn.appendChild(c);
                btn.setAttribute('aria-pressed', btn.classList.contains('active') ? 'true' : 'false');
            });

            const updateHeadings = () => {
                headings.forEach(h => {
                    let node = h.nextElementSibling;
                    let visible = 0;
                    while (node && !node.classList.contains('year-heading')) {
                        if (node.classList.contains('selected-publication') && !node.classList.contains('hidden')) visible++;
                        node = node.nextElementSibling;
                    }
                    h.classList.toggle('hidden', visible === 0);
                    let count = h.querySelector('.year-count');
                    if (!count) { count = document.createElement('span'); count.className = 'year-count'; h.appendChild(count); }
                    count.textContent = visible + (visible === 1 ? ' item' : ' items');
                });
            };

            const search = document.getElementById('pub-search');
            const empty = document.getElementById('pub-empty');
            let activeFilter = 'all';
            pubs.forEach(p => { p.dataset.search = p.textContent.replace(/\s+/g, ' ').toLowerCase(); });

            const apply = () => {
                const q = search ? search.value.trim().toLowerCase() : '';
                let shown = 0;
                pubs.forEach(p => {
                    const ok = (activeFilter === 'all' || p.classList.contains(activeFilter)) && (!q || p.dataset.search.includes(q));
                    p.classList.toggle('hidden', !ok);
                    if (ok) shown++;
                });
                if (empty) empty.hidden = shown !== 0;
                updateHeadings();
            };

            buttons.forEach(btn => {
                btn.addEventListener('click', () => {
                    buttons.forEach(b => { b.classList.remove('active'); b.setAttribute('aria-pressed', 'false'); });
                    btn.classList.add('active');
                    btn.setAttribute('aria-pressed', 'true');
                    activeFilter = btn.dataset.filter;
                    apply();
                });
            });
            if (search) search.addEventListener('input', apply);

            // Open a paper linked by #key
            if (location.hash) {
                const target = document.getElementById(location.hash.slice(1));
                if (target && target.classList.contains('selected-publication')) target.classList.add('pub-highlight');
            }
            updateHeadings();
        }
    });

    function normTitle(t) {
        return (t || '').toLowerCase().replace(/&amp;/g, '&').replace(/[^a-z0-9]+/g, ' ').trim();
    }

    function formatDate(iso) {
        const d = new Date(iso);
        if (isNaN(d)) return '';
        return d.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
    }

    function loadScholar() {
        const sources = [
            'https://raw.githubusercontent.com/KushagraIsTaken/KushagraIsTaken.github.io/main/scholar.json',
            'scholar.json'
        ];
        const tryFetch = (i) => i >= sources.length ? Promise.reject(new Error('no scholar data')) :
            fetch(sources[i], { cache: 'no-cache' })
                .then(r => { if (!r.ok) throw new Error(r.status); return r.json(); })
                .then(d => { if (typeof d.citations !== 'number') throw new Error('bad data'); return d; })
                .catch(() => tryFetch(i + 1));

        tryFetch(0).then(applyScholar).catch(() => { /* keep the numbers already in the HTML */ });
    }

    function applyScholar(data) {
        ['citations', 'h_index', 'i10_index'].forEach(k => {
            document.querySelectorAll('[data-scholar="' + k + '"]').forEach(el => {
                el.textContent = data[k].toLocaleString('en');
            });
        });
        const when = formatDate(data.updated);
        document.querySelectorAll('[data-scholar="updated"]').forEach(el => {
            el.textContent = when ? 'updated ' + when : 'live';
        });

        if (!Array.isArray(data.papers)) return;
        const byTitle = new Map(data.papers.map(p => [normTitle(p.title), p.citations]));
        const lookup = (title) => {
            const t = normTitle(title);
            if (byTitle.has(t)) return byTitle.get(t);
            for (const [k, v] of byTitle) {
                if (k.length > 30 && (k.startsWith(t.slice(0, 50)) || t.startsWith(k.slice(0, 50)))) return v;
            }
            return null;
        };

        document.querySelectorAll('.selected-publication').forEach(card => {
            if (card.querySelector('.pub-cites')) return;
            const titleEl = card.querySelector(':scope > a, :scope > .pub-title');
            if (!titleEl) return;
            const n = lookup(titleEl.textContent);
            if (!n) return;
            card.dataset.citations = n;
            const badge = document.createElement('span');
            badge.className = 'pub-cites';
            badge.title = 'Citations on Google Scholar';
            badge.innerHTML = '<i class="fa-solid fa-quote-left" aria-hidden="true"></i> ' + n + (n === 1 ? ' citation' : ' citations');
            const tags = card.querySelector('.pub-tags');
            if (tags) tags.appendChild(badge);
            else card.appendChild(badge);
        });
    }
})();

